function r(t){return t<10?`0${t}`:String(t)}function n(t){if(!t)return null;const e=new Date(t);return Number.isNaN(e.getTime())?null:e}function i(t){if(!t)return"-";const e=n(t);return e?`${e.getFullYear()}-${r(e.getMonth()+1)}-${r(e.getDate())} ${r(e.getHours())}:${r(e.getMinutes())}:${r(e.getSeconds())}`:t}function o(t){if(!t)return"-";if(/^\d{4}-\d{2}-\d{2}$/.test(t))return t;const e=n(t);return e?`${e.getFullYear()}-${r(e.getMonth()+1)}-${r(e.getDate())}`:t}export{o as a,i as f};
